INSERT INTO `kpis_id_space_backup_20260609` VALUES ('KPI 01','อัตราส่วนการตายมารดาไทยต่อการเกิดมีชีพแสนคน','ไม่เกิน 15 ต่อการเกิดมีชีพแสนคน','<',15,'{A}/{B}x100000','PP&P','จังหวัด','กลุ่มงานส่งเสริมสุขภาพ','ฤดีกาญจน์ บุตรดา','กรมอนามัย','KPI,KPR','https://drive.google.com/drive/folders/1oCRZPE1aNnD6iBuxbYz5bh2zKUyK2HI4?usp=sharing','2026-04-08 08:12:19.373','2025-12-23 03:55:41.199','2026-04-08 08:12:19.374'),('KPI 02','ร้อยละของเด็ก อายุ 0 - 5 ปี มีพัฒนาการสมวัย','ร้อยละ 88','>=',88,'{A}/{B}x100','PP&P','อำเภอ','กลุ่มงานส่งเสริมสุขภาพ','ฤดีกาญจน์ บุตรดา','กรมอนามัย','KPI,KPR,PA',NULL,'2026-06-02 16:53:33.736','2025-12-23 03:55:46.639','2026-06-02 16:53:33.738'),('KPI 03','ร้อยละของเด็กปฐมวัยที่มีพัฒนาการล่าช้าเข้าถึงบริการพัฒนาการและสุขภาพจิตที่ได้มาตรฐาน','ร้อยละ 30','>=',30,'{A}/{B}x100','PP&P','อำเภอ','กลุ่มงานส่งเสริมสุขภาพ','ฤดีกาญจน์ บุตรดา','กรมอนามัย','KPR',NULL,'2026-06-02 17:03:14.821','2025-12-23 03:57:18.594','2026-06-02 17:03:14.822'),('KPI 04','ร้อยละของเด็ก อายุ 0 – 5 ปี ฟันดีไม่มีผุ (Cavity Free)','ร้อยละ 80','>=',80,'{A}/{B}x100','PP&P','อำเภอ','กลุ่มงานทันตสาธารณสุข','สมพร น้อยสุขะ','กรมอนามัย','KPI,KPR',NULL,'2026-06-08 04:44:57.072','2025-12-23 03:58:12.261','2026-06-08 04:44:57.074'),('KPI 05','ร้อยละของชุมชนมีการดำเนินการจัดการสุขภาพที่เหมาะสมกับประชาชน','ร้อยละ 90 (คิดจากตำบลเป้าหมาย)','>=',89.97,'{A}/{B}x100','PP&P','อำเภอ','กลุ่มงานพัฒนาคุณภาพและรูปแบบบริการ',NULL,'กรมสนับสนุนบริการสุขภาพ','KPI,KPR',NULL,'2026-04-09 03:17:56.376','2025-12-23 03:59:48.055','2026-04-09 03:17:56.380'),('KPI 06','อัตราความรอบรู้ด้านสุขภาพของประชาชนไทย อายุ 15 ปี ขึ้นไป','ร้อยละ 92.93\r\n*** เชิงปริมาณ','>=',92.93,'{A}/{B}x100','PP&P','อำเภอ','กลุ่มงานส่งเสริมสุขภาพ','รัตนา ทั่งจ้อย','กรมอนามัย','KPI,KPR',NULL,'2026-06-05 04:36:44.064','2025-12-23 04:00:44.639','2026-06-08 04:07:34.871'),('KPI 07.1','ร้อยละการตรวจติดตามยืนยันวินิจฉัยกลุ่มสงสัยป่วย โรคเบาหวาน','ร้อยละ 70','>=',70,'{A}/{B}x100','PP&P','อำเภอ','กลุ่มงานควบคุมโรคไม่ติดต่อสุขภาพจิตและยาเสพติด','ดวงหทัย ใจมิภักดิ์','กรมควบคุมโรค','KPI,KPR',NULL,'2026-05-15 03:44:15.073','2026-02-05 08:57:40.267','2026-05-15 03:44:15.075'),('KPI 07.2','ร้อยละการตรวจติดตามยืนยันวินิจฉัยกลุ่มสงสัยป่วย โรคความดันโลหิตสูง','ร้อยละ 80','>=',80,'{A}/{B}x100','PP&P','อำเภอ','กลุ่มงานควบคุมโรคไม่ติดต่อสุขภาพจิตและยาเสพติด','ดวงหทัย ใจมิภักดิ์','กรมควบคุมโรค','KPI,KPR',NULL,'2026-04-08 18:49:07.104','2026-02-05 08:57:51.748','2026-04-08 18:49:07.106'),('KPI 07.3','ร้อยละผู้ป่วยโรคเบาหวานที่ควบคุมระดับน้ำตาลได้ดี','ร้อยละ 40','>=',40,'{A}/{B}x100','PP&P','อำเภอ','กลุ่มงานควบคุมโรคไม่ติดต่อสุขภาพจิตและยาเสพติด','ดวงหทัย ใจมิภักดิ์','กรมควบคุมโรค','KPR',NULL,'2026-04-08 19:23:07.648','2026-02-05 08:58:02.531','2026-04-08 19:23:07.650'),('KPI 07.4','ร้อยละผู้ป่วยโรคความดันโลหิตสูงที่ควบคุมความดันโลหิตได้ดี','ร้อยละ 60','>=',60,'{A}/{B}x100','SE','อำเภอ','กลุ่มงานควบคุมโรคไม่ติดต่อสุขภาพจิตและยาเสพติด','ดวงหทัย ใจมิภักดิ์','กรมควบคุมโรค','KPR',NULL,'2026-04-08 19:18:09.548','2026-02-05 08:58:11.944','2026-04-08 19:18:09.549'),('KPI 07.5','ร้อยละของผู้ป่วยเบาหวานชนิดที่ 2 ที่เข้าสู่โรคเบาหวานระยะสงบ (DM remission)','ร้อยละ 10','>=',10,'{A}/{B}x100','SE','อำเภอ','กลุ่มงานควบคุมโรคไม่ติดต่อสุขภาพจิตและยาเสพติด','ดวงหทัย ใจมิภักดิ์','กรมควบคุมโรค','KPR',NULL,'2026-04-08 19:27:25.404','2026-02-05 08:58:20.791','2026-04-08 19:27:25.406'),('KPI 08','อัตราการเสียชีวิตและบาดเจ็บจากอุบัติเหตุทางถนนในกลุ่มเด็กและเยาวชนลดลง (ช่วงวัย 1 - 18 ปี) ลดลงอย่างน้อยร้อยละ 3','เกณฑ์เป้าหมาย ลดลงอย่างน้อย ร้อยละ 3\r\nสูตรคำนวณ ((A-B)/B) x 100\r\nA = (จำนวนผู้เสียชีวิตรวมกับจำนวนผู้บาดเจ็บปี 2569) – (จำนวนผู้เสียชีวิตรวมกับจำนวนผู้บาดเจ็บค่าเฉลี่ย 3 ปี 2566 - 2568)\r\nB = จำนวนผู้เสียชีวิตรวมกับจำนวนผู้บาดเจ็บค่าเฉลี่ย ปี 2566 - 2568','<=',3,'({A}-{B})/{B}x100','PP&P','อำเภอ','กลุ่มงานควบคุมโรคไม่ติดต่อสุขภาพจิตและยาเสพติด','พิชญ์สุกานต์ พิชญพงศ์ศิริ','กรมควบคุมโรค','KPI,KPR','https://drive.google.com/file/d/12FJXY5w8W8WeYmaq3cC_3Ia_JzZnRmEI/view?usp=sharing','2026-05-06 08:58:47.502','2026-02-12 03:08:41.791','2026-06-08 03:38:47.967'),('KPI 09','ร้อยละความครอบคลุมของวัคซีนป้องกันหัด-คางทูม-หัดเยอรมัน เข็มที่ 2 (MMR2) ในเด็กอายุต่ำกว่า 3 ปี ระดับจังหวัด เป็นไปตามเป้าหมายการกำจัดโรคหัดตามพันธสัญญานานาชาติ','ร้อยละ 95','>=',95,'{A}/{B}x100','PP&P','อำเภอ','กลุ่มงานควบคุมโรคติดต่อ','ยุทธภูมิ วิจารณ์พล','กรมควบคุมโรค','KPI,KPR',NULL,'2026-06-08 05:07:49.493','2026-02-05 08:59:11.072','2026-06-08 05:07:49.496'),('KPI 10.1','ร้อยละของโรงพยาบาลที่พัฒนาอนามัยสิ่งแวดล้อมได้ตามเกณฑ์ GREEN & CLEAN Hospital Challenge ระดับมาตรฐานขึ้นไป (รพช. 8 แห่ง)','ร้อยละ 95','>=',95,'{A}/{B}x100','PP&P','อำเภอ','กลุ่มงานอนามัยสิ่งแวดล้อมและอาชีวอนามัย','กำหนด  มีจักร','กรมอนามัย','KPI,KPR',NULL,'2026-06-08 03:53:14.795','2026-02-05 09:03:45.194','2026-06-08 03:53:14.797'),('KPI 10.2','ร้อยละของโรงพยาบาลที่พัฒนาอนามัยสิ่งแวดล้อมได้ตามเกณฑ์ GREEN & CLEAN Hospital Challenge ระดับท้าทาย','ร้อยละ 30','>=',30,'{A}/{B}x100','PP&P','จังหวัด','กลุ่มงานอนามัยสิ่งแวดล้อมและอาชีวอนามัย','กำหนด  มีจักร','กรมอนามัย','KPI,KPR',NULL,'2026-06-08 03:55:42.563','2026-02-05 09:03:53.393','2026-06-08 03:55:42.565'),('KPI 11','ร้อยละผู้ป่วยไตเรื้อรัง stage 5 รายใหม่ ลดลงจากปีงบประมาณก่อนหน้า','ลดลง มากกว่าหรือเท่ากับ ร้อยละ 5','>=',5,'({B}-{A})/{B}x100','SE','อำเภอ','กลุ่มงานพัฒนาคุณภาพและรูปแบบบริการ',NULL,'กรมการแพทย์','KPI,KPR',NULL,'2026-05-27 07:53:16.563','2026-02-05 09:04:57.289','2026-05-27 07:53:16.564'),('KPI 12','อัตราตายผู้ป่วยติดเชื้อในกระแสเลือดแบบรุนแรงชนิด community-acquired','น้อยกว่าร้อยละ 24','<',24,'{A}/{B}x100','SE','อำเภอ','กลุ่มงานพัฒนาคุณภาพและรูปแบบบริการ',NULL,'กรมการแพทย์','KPI,KPR',NULL,'2026-05-27 07:27:07.811','2026-02-05 09:05:25.096','2026-05-27 07:27:07.814'),('KPI 13.1','อัตราความสำเร็จการรักษาผู้ป่วยวัณโรคปอดรายใหม่','ร้อยละ 88','>=',88,'{A}/{B}x100','SE','อำเภอ','กลุ่มงานควบคุมโรคติดต่อ','จอมพล','กรมควบคุมโรค','KPI,KPR',NULL,'2026-02-05 09:06:45.511','2026-02-05 09:06:45.511','2026-02-05 09:06:45.511'),('KPI 13.2','ผู้ต้องขังก่อนปล่อยตัวพ้นโทษได้รับการคัดกรองวัณโรคด้วยการถ่ายภาพรังสีทรวงอก (CXR)','มากกว่าหรือเท่ากับร้อยละ 35','>=',35,'{A}/{B}x100','SE','จังหวัด','กลุ่มงานควบคุมโรคติดต่อ','ยุทธภูมิ วิจารณ์พล','กรมควบคุมโรค','KPR',NULL,'2026-06-08 08:13:14.817','2026-02-05 09:12:41.967','2026-06-08 08:13:14.819'),('KPI 14','อัตราตายของผู้ป่วยโรคหลอดเลือดสมอง (Stroke: 160-164)','น้อยกว่า ร้อยละ 7','<',7,'{A}/{B}x100','SE','อำเภอ','กลุ่มงานควบคุมโรคไม่ติดต่อสุขภาพจิตและยาเสพติด',NULL,'กรมการแพทย์','KPI,KPR',NULL,'2026-06-03 06:00:52.836','2026-02-05 09:13:18.521','2026-06-03 06:00:52.838'),('KPI 14.1','ร้อยละผู้ป่วยโรคหลอดเลือดสมอง (I60-I64) ที่มีอาการไม่เกิน 72 ชั่วโมง ได้รับการรักษาใน Stroke Unit','มากกว่า ร้อยละ 80','>=',80,'{A}/{B}x100','SE','จังหวัด','กลุ่มงานควบคุมโรคไม่ติดต่อสุขภาพจิตและยาเสพติด','ชนัดดา เกิดแพร','กรมการแพทย์','KPI,KPR','https://drive.google.com/drive/folders/1oCRZPE1aNnD6iBuxbYz5bh2zKUyK2HI4?usp=sharing','2026-02-10 02:46:02.185','2026-02-09 08:42:32.117','2026-02-10 02:46:02.186'),('KPI 15.1','อัตราตายของผู้ป่วยโรคกล้ามเนื้อหัวใจตายเฉียบพลันชนิด STEMI','น้อยกว่าร้อยละ 9','<',9,'{A}/{B}x100','SE','อำเภอ','กลุ่มงานควบคุมโรคไม่ติดต่อสุขภาพจิตและยาเสพติด','พิชญ์สุกานต์ พิชญพงศ์ศิริ','กรมการแพทย์','KPI,KPR','https://drive.google.com/file/d/12FJXY5w8W8WeYmaq3cC_3Ia_JzZnRmEI/view?usp=sharing','2026-06-03 07:12:08.139','2026-02-05 09:14:12.649','2026-06-03 07:12:08.141'),('KPI 15.2','ร้อยละของการให้การรักษาผู้ป่วย STEMI ได้ตามมาตรฐานเวลาที่กำหนด','มากกว่าหรือเท่ากับ ร้อยละ 70','>=',70,'{A}/{B}x100','SE','อำเภอ','กลุ่มงานควบคุมโรคไม่ติดต่อสุขภาพจิตและยาเสพติด','ชนัดดา เกิดแพร','กรมการแพทย์','KPI,KPR','https://drive.google.com/drive/folders/1oCRZPE1aNnD6iBuxbYz5bh2zKUyK2HI4?usp=sharing','2026-06-03 08:44:48.196','2026-02-05 09:17:52.463','2026-06-03 08:44:48.198'),('KPI 15.2.1','ร้อยละของผู้ป่วย STEMI ที่ได้รับยาละลายลิ่มเลือดได้ตามมาตรฐานเวลาที่กําหนด','มากกว่าหรือเท่ากับ ร้อยละ 70\r\nร้อยละของผู้ป่วย STEMI ที่ได้รับยาละลายลิ่มเลือดได้ตามมาตรฐานเวลาที่กําหนด (≥ ร้อยละ 70)\r\nสูตรคํานวณ = (A/B) x 100\r\n• A = จํานวนครั้งการรักษาที่สามารถให้ยาละลายลิ่มเลือดภายใน 30 นาที นับจากผู้ป่วยได้รับ\r\nการวินิจฉัย STEMI (EKG diagnosis) เมื่อมาถึงโรงพยาบาล\r\n• B = จํานวนผู้ป่วย STEMI ที่มาถึงโรงพยาบาลและได้รับยาละลายลิ่มเลือดทั้งหมด','>=',70,'{A}/{B}x100','SE','อำเภอ','กลุ่มงานควบคุมโรคไม่ติดต่อสุขภาพจิตและยาเสพติด','ชนัดดา เกิดแพร','กรมการแพทย์','KPR','https://drive.google.com/drive/folders/1oCRZPE1aNnD6iBuxbYz5bh2zKUyK2HI4?usp=sharing','2026-06-03 09:28:36.792','2026-02-05 09:18:28.955','2026-06-03 09:28:36.793'),('KPI 15.2.2','ร้อยละของผู้ป่วย STEMI ที่ได้รับการทํา Primary PCI ได้ตามมาตรฐานเวลาที่กําหนด','มากกว่าหรือเท่ากับ ร้อยละ 70\r\nร้อยละของผู้ป่วย STEMI ที่ได้รับการทํา Primary PCI ได้ตามมาตรฐานเวลาที่กําหนด (≥ ร้อยละ 70)\r\nสูตรคํานวณ = (C/D) x 100\r\n• C = จํานวนครั้งที่สามารถส่งต่อไปที่โรงพยาบาลที่ทํา PCI ได้ ให้ได้รับการทํา Primary PCI ภายใน\r\n120 นาที นับจากผู้ป่วยได้รับการวินิจฉัย STEMI (EKG diagnosis) เมื่อมาถึงโรงพยาบาล\r\n• D = จํานวนผู้ป่วย STEMI ที่มาถึงโรงพยาบาลและได้รับการทํา Primary PCI ทั้งหมด','>=',70,'{A}/{B}x100','SE','จังหวัด','กลุ่มงานควบคุมโรคไม่ติดต่อสุขภาพจิตและยาเสพติด','ชนัดดา เกิดแพร','กรมการแพทย์','KPR','https://drive.google.com/drive/folders/1oCRZPE1aNnD6iBuxbYz5bh2zKUyK2HI4?usp=sharing','2026-06-03 09:32:06.072','2026-02-05 09:19:07.618','2026-06-03 09:32:06.074'),('KPI 15.3','อัตราตายของผู้ป่วยโรคกล้ามเนื้อหัวใจตายเฉียบพลันชนิด STEMI ภายใน 30 วัน นับจากผู้ป่วย\r\nได้รับการวินิจฉัย STEMI','น้อยกว่าร้อยละ 9\r\nอัตราตายของผู้ป่วยโรคกล้ามเนื้อหัวใจตายเฉียบพลันชนิด STEMI ภายใน 30 วัน นับจากผู้ป่วยได้รับ\r\nการวินิจฉัย STEMI (< ร้อยละ 9)\r\nสูตรคํานวณ = (A1/B1) x 100\r\n\r\n• A1 = จํานวนผู้ป่วยใน รหัส ICD10 - WHO - I21.0 - I21.3 ที่เสียชีวิตภายใน 30 วัน นับจากผู้ป่วยได้รับ\r\nการวินิจฉัย STEMI\r\n• B1 = จํานวนผู้ป่วยใน รหัส ICD10 - WHO - I21.0 - I21.3 ที่รับไว้รักษาในโรงพยาบาลทั้งหมด','<',9,'{A}/{B}x100','SE','อำเภอ','กลุ่มงานควบคุมโรคไม่ติดต่อสุขภาพจิตและยาเสพติด','ชนัดดา เกิดแพร','กรมการแพทย์','KPR','https://drive.google.com/drive/folders/1oCRZPE1aNnD6iBuxbYz5bh2zKUyK2HI4?usp=sharing','2026-06-03 10:00:15.901','2026-02-05 09:21:29.105','2026-06-03 10:00:15.902'),('KPI 16','อัตราตายทารกแรกเกิดอายุน้อยกว่าหรือเท่ากับ 28 วัน','น้อยกว่า 3.6 ต่อทารกเกิดมีชีพ 1000 คน','<',3.6,'{A}/{B}x1000','SE','อำเภอ','กลุ่มงานส่งเสริมสุขภาพ','ฤดีกาญจน์ บุตรดา','กรมการแพทย์','KPI,KPR','https://drive.google.com/drive/folders/1oCRZPE1aNnD6iBuxbYz5bh2zKUyK2HI4?usp=sharing','2026-06-02 17:05:37.712','2026-02-09 07:38:37.658','2026-06-02 17:05:37.713'),('KPI 16.1','จำนวนเตียง NICU ในเขตสุขภาพ','น้อยกว่า 1:300 ทารกเกิดมีชีพ','<',1,'{A}/{B}x100','SE','จังหวัด','กลุ่มงานส่งเสริมสุขภาพ','ฤดีกาญจน์ บุตรดา','กรมการแพทย์','KPR','https://drive.google.com/drive/folders/1oCRZPE1aNnD6iBuxbYz5bh2zKUyK2HI4?usp=sharing','2026-02-09 07:53:46.364','2026-02-06 02:14:51.770','2026-02-09 08:11:00.334'),('KPI 16.2','ร้อยละของการใช้นมแม่ Exclusive breastfeeding ในทารกป่วยเมื่อกลับบ้าน','มากกว่าหรือเท่ากับร้อยละ 65','>=',65,'{A}/{B}x100','SE','อำเภอ','กลุ่มงานส่งเสริมสุขภาพ','ฤดีกาญจน์ บุตรดา','กรมการแพทย์','KPR',NULL,'2026-04-08 08:41:30.062','2026-02-06 02:17:36.467','2026-04-08 08:41:30.064'),('KPI 17','ร้อยละความครอบคลุมการคัดกรองการได้ยินของทารกแรกเกิด','มากกว่า ร้อยละ 95','>=',95,'{A}/{B}x100','SE','อำเภอ','กลุ่มงานส่งเสริมสุขภาพ','ฤดีกาญจน์ บุตรดา','กรมการแพทย์','KPR','https://drive.google.com/drive/folders/1oCRZPE1aNnD6iBuxbYz5bh2zKUyK2HI4?usp=sharing','2026-06-02 17:11:58.385','2026-02-09 08:08:50.908','2026-06-02 17:11:58.387'),('KPI 18.1','ค่าเฉลี่ยคะแนนถ่วงน้ำหนักของความพร้อมด้านทรัพยากรและระบบการดูแลผูป่วย palliative care ของ โรงพยาบาลในจังหวัด (มิติที่ 1)','ค่าเฉลี่ยคะแนนถ่วงน้ำหนัก = 4\r\nค่าเฉลี่ย ระดับ 1 <= 20%\r\nค่าเฉลี่ย ระดับ 2  21% - 40%\r\nค่าเฉลี่ย ระดับ 3  41% - 60%\r\nค่าเฉลี่ย ระดับ 4  61% - 80%\r\nค่าเฉลี่ย ระดับ 5  81% - 100%','>=',80,'{A}/{B}x100','SE','อำเภอ','กลุ่มงานพัฒนาคุณภาพและรูปแบบบริการ','อุไรวรรณ นวลจีน','กรมการแพทย์','KPR','https://drive.google.com/drive/folders/1oCRZPE1aNnD6iBuxbYz5bh2zKUyK2HI4?usp=sharing','2026-05-27 07:30:02.015','2026-